### 🐍 Python (Flask)

```python
from flask import Flask, request, jsonify, Response
from platform_functions import getGreetingByIP   # ← adjust import path

app = Flask(__name__)

@app.route('/greet')
def greet():
    # 1️⃣ Extract client IP (Flask’s `request.remote_addr` works for most setups)
    ip = request.headers.get('X-Forwarded-For', request.remote_addr)

    try:
        # 2️⃣ Call the helper
        result = getGreetingByIP({"ip": ip})
        greeting = result["greeting"]
    except Exception as exc:
        # 3️⃣ Fallback to English
        app.logger.error(f"Greeting lookup failed: {exc}")
        greeting = "Hello!"

    # 4️⃣ Return plain text (or JSON if you like)
    return Response(greeting, mimetype='text/plain')
    # or: return jsonify(greeting=greeting)

if __name__ == '__main__':
    app.run(port=5000, debug=True)
```

