package com.example.demo;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.web.reactive.function.client.WebClient;
import reactor.core.publisher.Mono;

import java.util.Map;

@Service
public class GreetingService {

    private static final Map<String, String> GREETINGS = Map.of(
            "en", "Hello!",
            "fr", "Bonjour!",
            "es", "¡Hola!",
            "de", "Hallo!",
            "it", "Ciao!",
            "pt", "Olá!",
            "ja", "こんにちは！",
            "ko", "안녕하세요!",
            "zh", "你好！",
            "ru", "Привет!",
            "hi", "नमस्ते!"
    );

    private final WebClient client = WebClient.create();

    public Mono<GreetingResult> getGreetingByIp(String ip) {
        return client.get()
                .uri("https://ipapi.co/{ip}/json/", ip)
                .retrieve()
                .bodyToMono(String.class)
                .map(this::parseResponse);
    }

    private GreetingResult parseResponse(String json) {
        try {
            ObjectMapper mapper = new ObjectMapper();
            JsonNode node = mapper.readTree(json);
            String languages = node.path("languages").asText("en");
            String lang = languages.split(",")[0].split("-")[0];
            String greeting = GREETINGS.getOrDefault(lang, GREETINGS.get("en"));
            String country = node.path("country_code").asText();

            return new GreetingResult(greeting, lang, country, lang + "-" + country);
        } catch (Exception e) {
            throw new RuntimeException("Failed to parse geolocation response", e);
        }
    }

    // Simple DTO
    public static record GreetingResult(
            String greeting,
            String language,
            String country,
            String locale) {}
}
