const privateRanges = [
  { start: ipToLong('10.0.0.0'),      end: ipToLong('10.255.255.255') },
  { start: ipToLong('172.16.0.0'),   end: ipToLong('172.31.255.255') },
  { start: ipToLong('192.168.0.0'),  end: ipToLong('192.168.255.255') },
  { start: ipToLong('203.0.113.0'),  end: ipToLong('203.0.113.255') } // test‑net
];

function ipToLong(ip) {
  return ip.split('.').reduce((acc, octet) => (acc << 8) + Number(octet), 0) >>> 0;
}

function isPrivateOrTest(ip) {
  const n = ipToLong(ip);
  return privateRanges.some(r => n >= r.start && n <= r.end);
}

